import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);
import { emit } from "@/lib/event-bus";
import { getDb, searchIndex } from "@/server/db";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void; let detach: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); detach = searchService.registerSearchListeners(); });
afterAll(() => { detach(); cleanup(); });
const q = (t: any, query: string, extra: any = {}) => searchService.search(t.actors.member, { orgId: t.org.id, q: query, kinds: ["issue"], limit: 25, cursor: null, ...extra });

it("works", async () => {
  const s = await createTenant("tmpstarter", "starter");
  await issueService.createIssue(s.actors.member, issueInput(s.org.id, s.project.id, { title: "Release 2: hotfix" }));
  await issueService.createIssue(s.actors.member, issueInput(s.org.id, s.project.id, { title: "snake case" }));
  expect((await q(s, "Release 2: hotfix")).total).toBe(1);
  expect((await q(s, "100%")).total).toBe(0);
  expect((await q(s, "snake_case")).total).toBe(0);
  const e = await createTenant("tmpent", "enterprise");
  const issue = await issueService.createIssue(e.actors.member, issueInput(e.org.id, e.project.id, { title: "Some issue" }));
  const c = await commentService.createComment(e.actors.member, { orgId: e.org.id, issueId: issue.id, body: "this is flaky", parentId: null, mentionedUserIds: [] });
  expect((await q(e, "kind:comment flaky")).total).toBe(1);
  expect((await q(e, "in:comments flaky")).total).toBe(1);
  expect((await q(e, `project:${e.project.id} flaky`, { kinds: ["issue", "comment"] })).total).toBe(1);
  expect((await q(e, "flaky", { kinds: ["comment"], projectId: e.project.id })).total).toBe(1);
  await commentService.updateComment(e.actors.member, { orgId: e.org.id, commentId: c.id, body: "now wobbly" } as any);
  expect((await q(e, "wobbly", { kinds: ["comment"], projectId: e.project.id })).total).toBe(1);
  getDb().delete(searchIndex).run();
  await runSearchReindexJob(e.org.id);
  expect((await q(e, "wobbly", { kinds: ["comment"], projectId: e.project.id })).total).toBe(1);
  getDb().delete(searchIndex).run();
  await emit("search.reindex_requested", { orgId: e.org.id, actorId: null, subjectKind: "comment", subjectId: c.id });
  await emit("search.reindex_requested", { orgId: e.org.id, actorId: null, subjectKind: "project", subjectId: e.project.id });
  expect((await q(e, "wobbly", { kinds: ["comment"], projectId: e.project.id })).total).toBe(1);
  expect((await q(e, "kind:project", {})).total).toBe(1);
  await issueService.archiveIssue(e.actors.member, e.org.id, issue.id);
  await emit("search.reindex_requested", { orgId: e.org.id, actorId: null, subjectKind: "issue", subjectId: issue.id });
  expect((await q(e, "Some issue")).total).toBe(0);
  const g = await createTenant("tmpgrowth", "growth");
  const gi = await issueService.createIssue(g.actors.member, issueInput(g.org.id, g.project.id, { title: "growthy" }));
  await commentService.createComment(g.actors.member, { orgId: g.org.id, issueId: gi.id, body: "growthy comment", parentId: null, mentionedUserIds: [] });
  const r = await q(g, "growthy", { kinds: ["issue", "comment", "project"] });
  expect(r.total).toBe(1);
  expect((await q(g, "kind:comment growthy")).total).toBe(0);
});
EOF
